<script setup lang="ts">
import AppLoading from './AppLoading.vue'
import PurchaseEmptyState from './PurchaseEmptyState.vue'
import { computed,ref } from 'vue'
import { rows,state,mutate,setError } from '../state/household'
import { shell } from '../state/shell'
import { summary,occurrences } from '../lib/selectors'
import { money,inputMoney,parseMoney,today } from '../lib/money'
import type { Bill,Income,Occurrence } from '../api/models'
import FinanceForm from './FinanceForm.vue'
import FitMoney from './FitMoney.vue'
import AppDialog from './AppDialog.vue'
import { useSubmission } from '../lib/submission'
const totals=computed(()=>summary(state.records,shell.month)),due=computed(()=>occurrences(state.records,shell.month))
const form=ref<'income'|'bill'>(),editIncome=ref<Income>(),editBill=ref<Bill>(),paying=ref<Occurrence>(),payAmount=ref(''),payDate=ref(today()),linkedPurchase=ref('')
const {saving,error,retryId,run}=useSubmission()
function open(kind:'income'|'bill',entry?:Income,bill?:Bill){editIncome.value=entry;editBill.value=bill;form.value=kind}
function pay(item:Occurrence){paying.value=item;payAmount.value=inputMoney(item.expected_minor);payDate.value=today();linkedPurchase.value='';error.value=''}
async function recordPayment(){await run(()=>mutate('bill.pay',{bill_id:paying.value!.bill_id,due_date:paying.value!.due_date,transaction_date:payDate.value,amount_minor:parseMoney(payAmount.value,false),purchase_id:linkedPurchase.value||null}),()=>{paying.value=undefined})}
async function remove(id:string,revision:number){if(!confirm('Remove this entry? Its change history will remain.'))return;try{await mutate('income.delete',{expected_revision:revision},id)}catch(e){setError(e)}}
</script>
<template><div class="section-heading"><h2>Income, savings & commitments</h2></div><div class="metrics"><section class="card"><small>Expected income</small><FitMoney class="metric-value" :amount="totals.expected" /><small>Planning only</small></section><section class="card"><small>Recorded income this month</small><FitMoney class="metric-value" :amount="totals.actualIncome" /><small>Actual receipts</small></section><section class="card sage"><small>Recorded savings</small><FitMoney class="metric-value" :amount="totals.savingsBalance" /><small>Manually tracked through this month</small></section></div><div class="stack">
 <details class="card"><summary>Income entries</summary><button class="button small" :disabled="!state.online" @click="open('income')">+ Record income</button><div v-for="entry in rows('income').filter(x=>x.transaction_date.startsWith(shell.month))" :key="entry.id" class="row"><div class="row-main"><strong>{{entry.description}}</strong><p>{{entry.transaction_date}} · {{rows('users').find(x=>x.id===entry.user_id)?.name}}</p></div><strong>{{money(entry.amount_minor)}}</strong><button class="button small" :disabled="!state.online" @click="open('income',entry)">Edit income</button><button class="icon-button" :disabled="!state.online" :aria-label="'Delete income '+entry.description" @click="remove(entry.id,entry.revision)">×</button></div><PurchaseEmptyState v-if="!rows('income').some(x=>x.transaction_date.startsWith(shell.month))" /></details>
 <details class="card"><summary>Monthly bills</summary><button class="button small" :disabled="!state.online" @click="open('bill')">+ Add monthly bill</button><PurchaseEmptyState v-if="!due.length" /><div v-for="item in due" :key="item.id" class="row"><div class="row-main"><strong>{{item.name}}</strong><p>Due {{item.due_date}}</p></div><strong>{{money(item.expected_minor)}}</strong><span v-if="item.purchase_id" class="pill">Recorded</span><button v-else class="button small" :disabled="!state.online" @click="pay(item)">Record payment</button></div><details class="section-space"><summary>Manage bill definitions</summary><PurchaseEmptyState v-if="!rows('recurring-bills').length" /><div v-for="bill in rows('recurring-bills')" :key="bill.id" class="row"><div class="row-main"><strong>{{bill.name}}</strong><p>{{bill.active?'Active':'Inactive'}} · Day {{bill.due_day}} each month</p></div><button class="button small" :disabled="!state.online" @click="open('bill',undefined,bill)">Edit bill</button></div></details><p class="text-small">Upcoming bills are commitments. Only a recorded payment counts as spending.</p></details>
 </div><FinanceForm v-if="form" :kind="form" :entry="editIncome" :bill="editBill" @close="form=undefined" /><AppDialog v-if="paying" title="Record a bill payment" @close="paying=undefined"><AppLoading v-if="saving" compact /><form @submit.prevent="recordPayment"><div v-if="error" class="notice error" role="alert">{{error}}</div><fieldset :disabled="saving||!!retryId"><p>{{paying.name}} · Due {{paying.due_date}}</p><label>Payment amount ($)<input v-model="payAmount" inputmode="decimal" required /></label><label>Payment date<input v-model="payDate" type="date" required /></label><label>Link an existing purchase<select v-model="linkedPurchase"><option value="">Create a new purchase</option><option v-for="p in rows('purchases').filter(x=>!x.bill_id&&x.category_id===rows('recurring-bills').find(b=>b.id===paying?.bill_id)?.category_id)" :key="p.id" :value="p.id">{{p.item}} · {{money(p.amount_minor)}}</option></select></label></fieldset><button class="button primary" :disabled="saving">{{saving?'Saving…':retryId?'Retry saved submission':'Record payment'}}</button></form></AppDialog></template>
